#include <string.h>
#include <stdio.h>
#include "picotls.h"
#include "picotls/asn1.h"
#include "picotls/minicrypto.h"

void log_printf(void *ctx, const char *format, ...)
{
    (void)ctx;
    (void)format;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <poc_file>\n", argv[0]);
        return 1;
    }
    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);
