    if (bytes_max > fsize - 2) bytes_max = fsize - 2;

    uint8_t *bytes = malloc(bytes_max);
    memcpy(bytes, data + 2, bytes_max);

    ptls_asn1_validation(bytes, bytes_max, &ctx);

    free(bytes);
    free(data);
    return 0;
}
